installer-gui-script.script:
function hasPython() {
  var paths = [
    "/Library/Frameworks/Python.framework/Versions/Current/bin/python3",
    "/Library/Developer/CommandLineTools/usr/bin/python3",
    "/Applications/Xcode.app/Contents/Developer/usr/bin/python3",
    "/opt/homebrew/bin/python3",
    "/usr/local/bin/python3"
  ];
  for (var i = 0; i < paths.length; i++) {
    if (system.files.fileExistsAtPath(paths[i])) return true;
  }
  my.result.type = "Fatal";
  my.result.title = "Python 3 is needed first";
  my.result.message = "Agent Presence runs on Python 3.9 or newer. Open Terminal and run  xcode-select --install  (or install Python from python.org), then open this installer again.";
  return false;
}
